+// arguments returns the matched function's parameter identifiers, excluding
+// the receiver.
+func (d *funcTemplateData) arguments() []string {
+	if !d.argsCollected {
+		args := collectArguments(d.funcDecl)
+		if ast.HasReceiver(d.funcDecl) {
+			args = args[1:]
+		}
+		d.args = args
+		d.argsCollected = true
+	}
+	return d.args
