`ImportAliasMap` treats `Imports` and `Decls` as either/or (typename.go:130-145) — when
`Imports` is non-empty, `Decls` is never consulted, even if it holds additional import
specs. That's fine for parser-produced files, but the precedence itself is currently
unverified by any test. Add a subtest asserting `Imports` wins over `Decls` when both
are populated.

```suggestion
	})

	t.Run("Imports takes precedence when both Imports and Decls contain specs", func(t *testing.T) {
		file := &dst.File{
			Imports: []*dst.ImportSpec{
				{Path: &dst.BasicLit{Value: `"net/http"`}},
			},
			Decls: []dst.Decl{
				&dst.GenDecl{
					Tok: token.IMPORT,
					Specs: []dst.Spec{
						&dst.ImportSpec{
							Name: &dst.Ident{Name: "ignored"},
							Path: &dst.BasicLit{Value: `"other/pkg"`},
						},
					},
				},
			},
		}

		imports := ImportAliasMap(file)
		assert.Len(t, imports, 1)
		assert.Equal(t, "net/http", imports["http"])
		assert.NotContains(t, imports, "ignored")
	})
